package app.gymlog;

import android.content.Context;
import android.content.SharedPreferences;
import android.media.AudioAttributes;
import android.media.AudioFocusRequest;
import android.media.AudioManager;
import android.media.MediaPlayer;

/**
 * Background music (res/raw/music.ogg, an original loop generated by tools/gen_music.py).
 *
 * - Plays only while one of the app's screens is visible; pauses when the app is closed.
 * - The note button in the top bar turns it on/off; the choice is remembered.
 * - If another app is already playing music when the app opens, ours does not start
 *   automatically (tap the note button to start it anyway).
 * - Pauses for calls and other apps' audio (audio focus).
 */
final class Music implements AudioManager.OnAudioFocusChangeListener {
    static boolean sDisabledForTests;
    private static final String PREFS = "settings";
    private static final String KEY_ON = "music_on";
    private static final float VOLUME = 0.45f;
    private static Music sInstance;

    private final Context app;
    private MediaPlayer player;
    private AudioFocusRequest focusRequest;
    private int visibleScreens;
    private boolean playing;
    private boolean resumeOnFocusGain;

    static synchronized void resetForTests() {
        sInstance = null;
    }

    static synchronized Music get(Context c) {
        if (sInstance == null) sInstance = new Music(c.getApplicationContext());
        return sInstance;
    }

    private Music(Context app) {
        this.app = app;
    }

    private SharedPreferences prefs() {
        return app.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
    }

    boolean isEnabled() {
        return prefs().getBoolean(KEY_ON, true);
    }

    boolean isPlaying() {
        return playing;
    }

    void onScreenStart() {
        visibleScreens++;
        if (visibleScreens == 1 && isEnabled() && !playing) {
            AudioManager am = (AudioManager) app.getSystemService(Context.AUDIO_SERVICE);
            if (am != null && am.isMusicActive()) return; // the user listens to their own music
            start();
        }
    }

    void onScreenStop() {
        visibleScreens = Math.max(0, visibleScreens - 1);
        if (visibleScreens == 0) pause(false);
    }

    /** Note button: on -> off, off -> on. Returns true if music is now playing. */
    boolean toggle() {
        if (playing) {
            pause(false);
            prefs().edit().putBoolean(KEY_ON, false).apply();
        } else {
            prefs().edit().putBoolean(KEY_ON, true).apply();
            start();
        }
        return playing;
    }

    private void start() {
        if (sDisabledForTests) return;
        try {
            if (player == null) {
                AudioAttributes attrs = new AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_MEDIA)
                        .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                        .build();
                AudioManager am = (AudioManager) app.getSystemService(Context.AUDIO_SERVICE);
                int session = am != null ? am.generateAudioSessionId() : 0;
                player = MediaPlayer.create(app, R.raw.music, attrs, session);
                if (player == null) return;
                player.setLooping(true);
            }
            if (!requestFocus()) return;
            player.setVolume(VOLUME, VOLUME);
            player.start();
            playing = true;
        } catch (RuntimeException e) {
            playing = false;
        }
    }

    private void pause(boolean keepFocusListener) {
        resumeOnFocusGain = false;
        if (player != null) {
            try {
                if (player.isPlaying()) player.pause();
            } catch (RuntimeException ignored) {
                // player in a bad state: nothing to pause
            }
        }
        playing = false;
        if (!keepFocusListener) abandonFocus();
    }

    private boolean requestFocus() {
        AudioManager am = (AudioManager) app.getSystemService(Context.AUDIO_SERVICE);
        if (am == null) return true;
        if (focusRequest == null) {
            focusRequest = new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN)
                    .setAudioAttributes(new AudioAttributes.Builder()
                            .setUsage(AudioAttributes.USAGE_MEDIA)
                            .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                            .build())
                    .setOnAudioFocusChangeListener(this)
                    .build();
        }
        return am.requestAudioFocus(focusRequest) == AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
    }

    private void abandonFocus() {
        AudioManager am = (AudioManager) app.getSystemService(Context.AUDIO_SERVICE);
        if (am != null && focusRequest != null) am.abandonAudioFocusRequest(focusRequest);
    }

    @Override
    public void onAudioFocusChange(int change) {
        switch (change) {
            case AudioManager.AUDIOFOCUS_LOSS:
                pause(false); // another app took over (e.g. the user started their own music)
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT:
                if (playing) {
                    pause(true);
                    resumeOnFocusGain = true;
                }
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
                if (player != null && playing) player.setVolume(VOLUME / 4, VOLUME / 4);
                break;
            case AudioManager.AUDIOFOCUS_GAIN:
                if (player != null && playing) player.setVolume(VOLUME, VOLUME);
                if (resumeOnFocusGain && visibleScreens > 0 && isEnabled()) start();
                resumeOnFocusGain = false;
                break;
            default:
                break;
        }
    }
}
